ps2026-tbl:
MODELS['ps2026-tbl'] = (C) => {
  const cm=C.cm, TH=C.THREE, W=C.w, D=C.d, H=C.h;
  const TT=cm(2.6), yU=H-TT;
  const birch=C.col.clone().lerp(new TH.Color(0xffffff),0.20);
  if(C.col2) birch.lerp(C.col2,0.16);
  const mTop=C.M(C.col,{wood:true,rough:.42,clear:.36,clearRough:.24});
  const mLeg=C.M(birch,{wood:true,rough:.46,clear:.30,clearRough:.28});
  const mRed=C.M(0xC4262E,{rough:.40,metal:.18,clear:.55,clearRough:.22});
  const mHw=C.m.steel;
  /* 松木实木厚板台面：平面四角圆角 + 边缘倒圆 */
  const bv=cm(0.35), rr=cm(1.8), hx=W/2, hz=D/2, tp=[];
  [[hx-rr,hz-rr,0],[rr-hx,hz-rr,Math.PI/2],[rr-hx,rr-hz,Math.PI],[hx-rr,rr-hz,Math.PI*1.5]]
    .forEach(c=>{ for(let i=0;i<=3;i++){ const a=c[2]+i*Math.PI/6; tp.push([c[0]+rr*Math.cos(a),c[1]+rr*Math.sin(a)]); } });
  C.ext(tp, TT, mTop, 0, H-bv, 0, 'xz', bv);
  /* 两组桦木 X 形交叉腿：位于短边方向的竖直面内，腿杆首尾按水平面切口 */
  const legX=W/2-cm(6.5), t=cm(3.4), lb=cm(0.3);
  const zT=D/2-cm(6.0), zB=D/2-cm(7.0);
  const e=cm(2.3)*Math.hypot(yU,zT+zB)/yU;
  const yX=yU*zB/(zT+zB);
  const legPts=(zt,zb)=>[[-zt-e,yU],[-zt+e,yU],[-zb+e,0],[-zb-e,0]];
  const pA=legPts(-zT,zB), pB=legPts(zT,-zB);
  [-1,1].forEach(s=>{
    const X=s*legX, xo=(s<0?X-t:X), xi=(s<0?X:X-t);
    C.ext(pA, t, mLeg, xo+lb, 0, 0, 'zy', lb);
    C.ext(pB, t, mLeg, xi+lb, 0, 0, 'zy', lb);
    /* 端头铰接横梁 + 折叠铰链 */
    C.box(t*2, cm(3.3), (zT-cm(2.5))*2, mLeg, X, yU-cm(3.3), 0);
    [-1,1].forEach(q=> C.box(t*2.2, cm(0.7), cm(5), mHw, X, yU-cm(0.8), q*(zT-cm(1.2))));
    /* 斜向支撑板：从交叉点斜升到台面下中部的安装座 */
    const bX=s*(W/2-cm(45)), dy=yU-yX;
    const eb=cm(1.3)*Math.hypot(bX-X,dy)/dy;
    C.ext([[X-eb,yX],[X+eb,yX],[bX+eb,yU],[bX-eb,yU]], cm(10), mLeg, 0, 0, -cm(4.7), 'xy', cm(0.3));
    C.box(cm(9), cm(1.9), cm(12), mLeg, bX, yU-cm(1.9), 0);
    /* 交叉点外侧的红色三瓣蝶形旋钮 —— 全桌唯一亮色 */
    const kx=(s<0?X-t:X+t);
    const kn=C.cyl(cm(1.5),cm(1.5),cm(1.7),mRed,0,0,0,18);
    kn.rotation.z=Math.PI/2; kn.position.set(kx+s*cm(0.5), yX, 0);
    for(let i=0;i<3;i++){
      const a=i*2*Math.PI/3+0.6;
      const lo=C.sph(cm(1.35), mRed, kx+s*cm(0.45), yX+cm(1.8)*Math.sin(a), cm(1.8)*Math.cos(a), 14);
      lo.scale.x=0.52;
    }
  });
};

ps2026-tbl-drw:
MODELS['ps2026-tbl-drw'] = (C) => {
  const cm = C.cm, T = C.THREE, PI = Math.PI;
  const W = C.w, D = C.d, H = C.h;
  const topT   = cm(2.7);
  const railH  = cm(6.3);
  const legW   = cm(5.5);
  const over   = cm(0.5);
  const railT  = cm(1.9);
  const railBk = cm(1.4);
  const glideH = cm(0.4);
  const topY   = H - topT;
  const railY  = topY - railH;
  const legOX  = W/2 - over, legIX = legOX - legW, legCX = legOX - legW/2;
  const legOZ  = D/2 - over, legIZ = legOZ - legW, legCZ = legOZ - legW/2;
  const railOX = legOX - railBk, railOZ = legOZ - railBk;

  const woodAt = (f) => C.M(C.col.clone().multiplyScalar(f), {wood:true, rough:.45, clear:.32, clearRough:.22});
  const wood  = woodAt(1.00);
  const woodL = woodAt(1.04);
  const woodD = woodAt(0.94);
  const joint = C.M(C.col.clone().multiplyScalar(0.74), {wood:true, rough:.62, clear:.10});
  const blue  = C.M(C.col2 ? C.col2.clone() : new T.Color(0x1c63b8), {rough:.5, clear:.25, clearRough:.3});
  const glideM= C.M(0xb0aa9f, {rough:.8});

  const tone = [1.00, 0.95, 1.05, 0.97, 1.03, 0.93];
  const NP = 6, pd = D/NP, tr = cm(0.19);
  C.rep(NP, (i) => {
    C.rb(W - 2*tr, topT - 2*tr, pd, tr, woodAt(tone[i]), 0, topY + tr, -D/2 + pd*(i+0.5), 2);
  });

  for (const sx of [-1,1]) C.box(railT, railH, legIZ*2, woodD, sx*(railOX - railT/2), railY, 0);

  const dfH = railH - cm(0.55), dfW = legIX*2 - cm(0.6), dfY = railY + cm(0.10), dr = cm(0.25);
  for (const sz of [-1,1])
    C.rb(dfW - 2*dr, dfH - 2*dr, railT, dr, woodL, 0, dfY + dr, sz*(railOZ - railT/2), 3);

  const dSide = cm(1.2), dLen = D - 2*railT;
  for (const sx of [-1,1]) {
    C.box(dSide, dfH, dLen, wood, sx*(dfW/2 - dSide/2), dfY, 0);
    C.box(cm(2.4), cm(1.3), dLen, woodD, sx*(dfW/2 + cm(1.15)), railY + cm(0.35), 0);
  }
  const bw = dfW - 2*dSide, bY = railY + cm(1.10);
  C.box(bw, cm(0.5), dLen - cm(0.4), woodL, 0, bY, 0);
  C.box(bw - cm(0.1), cm(0.14), dLen - cm(0.5), blue, 0, bY + cm(0.5), 0);

  const legH = topY - glideH, lr = cm(0.3);
  const spY = railY + cm(0.35), spH = railH - cm(0.8), spW = cm(1.2), spT = cm(0.07);
  for (const sx of [-1,1]) for (const sz of [-1,1]) {
    const lg = C.rb(legH - 2*lr, legW - 2*lr, legW, lr, wood, 0, 0, 0, 3);
    lg.rotation.z = PI/2;
    lg.position.set(sx*legCX, glideH + legH/2, sz*legCZ);
    C.cyl(cm(2.0), cm(2.0), glideH + cm(0.06), glideM, sx*legCX, 0, sz*legCZ, 16);
    for (const o of [-cm(1.03), cm(1.03)]) {
      C.box(spT, spH, spW, joint, sx*(legOX + cm(0.02)), spY, sz*legCZ + o);
      C.box(spW, spH, spT, joint, sx*legCX + o, spY, sz*(legOZ + cm(0.02)));
    }
  }
};

ps2026-side:
MODELS['ps2026-side'] = (C) => {
  const T3 = C.THREE, PI = Math.PI;
  const X = v => C.w * v / 50, Y = v => C.h * v / 51, Z = v => C.d * v / 40;
  const V = (x, y, z) => new T3.Vector3(X(x), Y(y), Z(z));
  const R = C.cm(0.9), th = C.cm(1.8), bev = C.cm(0.28);
  const topM  = C.M(C.col, {rough:.68, clear:.13, clearRough:.55});
  const tubeM = C.M((C.col2 ? C.col2.clone() : C.col.clone().multiplyScalar(.86)),
                    {rough:.32, metal:.30, clear:.50, clearRough:.14});
  const darkM = C.M(C.col.clone().multiplyScalar(.14), {rough:.66});
  const clipM = C.M(0x9aa0a6, {rough:.42, metal:.5});
  const seg = (a, b, r, mat) => {
    const d = b.clone().sub(a), L = d.length(), rr = r || R;
    if (L < 1e-5) return;
    const m = C.tube(L + 2 * rr, rr, mat || tubeM, (a.x + b.x) / 2, (a.y + b.y) / 2, (a.z + b.z) / 2, 'y');
    m.quaternion.setFromUnitVectors(new T3.Vector3(0, 1, 0), d.normalize());
  };
  const poly = p => { for (let i = 0; i < p.length - 1; i++) seg(p[i], p[i + 1]); };
  const bz3 = (p0, p1, p2, p3, n) => { const o = [];
    for (let i = 0; i <= n; i++) { const t = i / n, u = 1 - t, a = u*u*u, b = 3*u*u*t, c = 3*u*t*t, d = t*t*t;
      o.push(new T3.Vector3(a*p0.x+b*p1.x+c*p2.x+d*p3.x, a*p0.y+b*p1.y+c*p2.y+d*p3.y, a*p0.z+b*p1.z+c*p2.z+d*p3.z)); }
    return o; };
  const bz2 = (p0, p1, p2, n) => { const o = [];
    for (let i = 0; i <= n; i++) { const t = i / n, u = 1 - t, a = u*u, b = 2*u*t, c = t*t;
      o.push(new T3.Vector3(a*p0.x+b*p1.x+c*p2.x, a*p0.y+b*p1.y+c*p2.y, a*p0.z+b*p1.z+c*p2.z)); }
    return o; };
  const arc = (cx, cz, r, a0, a1, n, out) => {
    for (let i = 0; i <= n; i++) { const a = a0 + (a1 - a0) * i / n;
      out.push([X(cx + Math.cos(a) * r), Z(cz + Math.sin(a) * r)]); } };
  const xi = -0.25, rI = 0.9, rO = 3.5, nz = -10, nh = 0.95, ntip = -7.7;
  const half = [];
  arc(xi - rI, -20 + rI, rI, 0, -PI/2, 4, half);
  arc(-25 + rO, -20 + rO, rO, -PI/2, -PI, 7, half);
  arc(-25 + rO,  20 - rO, rO, PI, PI/2, 7, half);
  arc(xi - rI,  20 - rI, rI, PI/2, 0, 4, half);
  half.push([X(xi), Z(nz + nh)]);
  half.push([X(ntip + nh), Z(nz + nh)]);
  arc(ntip + nh, nz, nh, PI/2, PI*1.5, 6, half);
  half.push([X(xi), Z(nz - nh)]);
  C.ext(half, th, topM, 0, C.h - bev, 0, 'xz', bev);
  C.ext(half.map(p => [-p[0], -p[1]]), th, topM, 0, C.h - bev, 0, 'xz', bev);
  const yA = 1.2;
  const frame = s => {
    const xa = y => s * (22.5 - 0.3176 * y), zf = y => s * (17 - 0.1373 * y);
    const p = bz3(V(0, 70.1, 0), V(0, 70.1, s*3.4), V(s*2.5, 63, s*8.4), V(xa(51), 51, zf(51)), 8);
    p.push(V(xa(30), 30, zf(30)));
    p.push(V(xa(6), 6, zf(6)));
    bz2(V(xa(6), 6, zf(6)), V(s*22.4, yA, s*17.2), V(s*22.4, yA, s*13.8), 4).slice(1).forEach(q => p.push(q));
    p.push(V(s*22.4, yA, -s*13.8));
    bz2(V(s*22.4, yA, -s*13.8), V(s*22.4, yA, -s*17.2), V(xa(6), 6, -zf(6)), 4).slice(1).forEach(q => p.push(q));
    p.push(V(xa(48.6), 48.6, -zf(48.6)));
    poly(p);
    if (s > 0) { const a = p[2], b = p[3], md = a.clone().add(b).multiplyScalar(.5);
      const bd = C.cyl(R*1.26, R*1.26, C.cm(2.0), darkM, 0, 0, 0, 16);
      bd.position.copy(md); bd.quaternion.setFromUnitVectors(new T3.Vector3(0,1,0), b.clone().sub(a).normalize()); }
    seg(V(xa(36), 36, zf(36)), V(xa(36), 36, -zf(36)));
    C.rb(X(2.4), Y(1.5), Z(3.0), C.cm(0.3), darkM, X(xa(48.6)), Y(47.8), Z(-zf(48.6)), 2);
    for (const t of [1, -1])
      C.rb(X(2.4), Y(0.6), Z(3.3), C.cm(0.18), darkM, X(s*22.4), C.cm(0.18), Z(t*s*12.6), 2);
  };
  frame(1); frame(-1);
  for (const s of [1, -1])
    C.rb(X(1.5), Y(0.75), Z(1.8), C.cm(0.24), clipM, X(-s*1.2), C.h - Y(0.42), Z(-s*7.4), 3);
};

saltsjobaden:
MODELS['saltsjobaden'] = (C) => {
  const cm = C.cm, S = C.spec || {};
  const fab  = C.M(C.col, {fabric:true, rough:.93, sheen:.16});
  const wood = C.M(C.col2 || '#D9BE92', {wood:'birch', rough:.40, clear:.42, clearRough:.16});
  const glide= C.M('#3b3e43', {rough:.75});

  /* 尺寸(cm)：机身 93×82，离地 17，扶手/靠背框顶 64，座高 46，靠垫顶 90 */
  const HW=(S.w||93)/2, HD=Math.min((S.d||88)/2, 41), TOP=S.h||90, SH=S.seatH||46;
  const LEG=17, ARM=12, IN=HW-ARM, DECK=SH-15, BACKF=-HD+13, B=2.0, ARMTOP=64;

  /* U 形框架平面轮廓（两侧扶手 12cm + 后背板 13cm，正面镂空），拐角带圆角 */
  const corner=[
    [-(HW-B), -(HD-B), 0.5], [ (HW-B), -(HD-B), 0.5],
    [ (HW-B),  (HD-B), 0.5], [ (IN+B),  (HD-B), 0.5],
    [ (IN+B), (BACKF-B), 6.0], [-(IN+B), (BACKF-B), 6.0],
    [-(IN+B),  (HD-B), 0.5], [-(HW-B),  (HD-B), 0.5]
  ];
  const poly=[], N=corner.length;
  for(let i=0;i<N;i++){
    const p=corner[i], a=corner[(i+N-1)%N], q=corner[(i+1)%N];
    const ax=a[0]-p[0], az=a[1]-p[1], qx=q[0]-p[0], qz=q[1]-p[1];
    const la=Math.hypot(ax,az), lq=Math.hypot(qx,qz);
    const r=Math.min(p[2], la*0.45, lq*0.45);
    const s1x=p[0]+ax/la*r, s1z=p[1]+az/la*r, s2x=p[0]+qx/lq*r, s2z=p[1]+qz/lq*r;
    for(let k=0;k<=4;k++){ const t=k/4, u=1-t;
      poly.push([cm(u*u*s1x+2*u*t*p[0]+t*t*s2x), cm(u*u*s1z+2*u*t*p[1]+t*t*s2z)]); }
  }
  /* 一体挤出：所有棱边圆角，扶手顶面与背板顶面齐平在 64cm */
  C.ext(poly, cm(ARMTOP-LEG), fab, 0, cm(ARMTOP-B), 0, 'xz', cm(B));

  /* 座箱前围板（17→31cm） */
  C.rb(cm(2*IN+1.4-1.8), cm((DECK-LEG)-1.8), cm(HD-BACKF+2), cm(0.9), fab,
       0, cm(LEG+0.9), cm((BACKF-2+HD)/2), 3);

  /* 整块厚坐垫：68×15×63，顶面 46cm，前缘略外凸 */
  C.rb(cm(2*IN-1-5.6), cm(15-5.6), cm(63), cm(2.8), fab, 0, cm(DECK+2.8), cm(10.5), 4);

  /* 松软独立靠垫：斜靠背板、顶端 90cm，外圈+饱满前片形成包边缝 */
  const bg=new C.THREE.Group(); C.g.add(bg);
  bg.add(C.rb(cm(57), cm(37), cm(16), cm(5),   fab, 0, cm(-18.5), 0, 4));
  bg.add(C.rb(cm(57), cm(37), cm(8),  cm(3),   fab, 0, cm(-18.5), cm(5.2), 4));
  bg.rotation.x = -0.16;
  bg.position.set(0, cm(TOP-24.5), cm(BACKF+11.3));

  /* 4 条 Bjurvalla 桦木方腿：截面约 6cm 见方、微收分、垂直，底部深色脚垫 */
  C.rep(4,(i)=>{
    const x=((i&1)?1:-1)*cm(HW-7.5), z=((i&2)?1:-1)*cm(HD-9);
    C.cyl(cm(4.25), cm(3.6), cm(LEG), wood, x, 0, z, 4).rotation.y=Math.PI/4;
    C.cyl(cm(3.5), cm(3.5), cm(0.35), glide, x, 0, z, 4).rotation.y=Math.PI/4;
  });
};

dyvlinge:
MODELS['dyvlinge'] = (C) => {
  const cm = C.cm;
  /* Kelinge 粗条灯芯绒：主色 C.col（微光泽），缝线/包扣用辅色 C.col2 或压暗一档；五金统一高亮镀铬 */
  const fab   = C.M(C.col, {fabric:true, rough:.90, sheen:.34});
  const seamC = C.col2 ? C.col2.clone() : C.col.clone().multiplyScalar(0.78);
  const fabD  = C.M(seamC, {fabric:true, rough:.94});
  const chrome= C.M(0xc2c6ca, {rough:.09, metal:1, clear:.50, clearRough:.05});
  const blk   = C.M(0x1e2024, {rough:.52, metal:.25});
  const halfD = C.d/2;

  /* ========== 靠背：后倾 24°、上窄下宽的圆润梯形大软枕（3×3 绗缝 + 4 颗包扣 + 上下两道包边缝） ========== */
  const th = 0.42, cB = Math.cos(th), sB = Math.sin(th);
  const BT = cm(17), BL = cm(36), BW = C.w*0.90, bev = cm(4.0);
  const bpy = C.h - ((BL/2)*cB + (BT-2*bev)*sB);
  const bpz = -halfD + ((BL/2-bev)*sB + bev*cB);
  const bxf = (lx,ly,lz) => [lx, bpy + ly*cB + lz*sB, bpz - ly*sB + lz*cB];
  const hl = BL/2, rc = cm(9.5), cw = BW/2-rc, ch = hl-rc, padPts = [];
  for(const c of [[cw,ch,0],[-cw,ch,Math.PI/2],[-cw,-ch,Math.PI],[cw,-ch,-Math.PI/2]])
    for(let i=0;i<=5;i++){ const a = c[2]+i/5*Math.PI/2, y = c[1]+Math.sin(a)*rc;
      padPts.push([(c[0]+Math.cos(a)*rc)*(1-0.14*y/BL), y]); }
  C.ext(padPts, BT, fab, 0, bpy, bpz, 'xy', bev).rotation.x = -th;
  let p = bxf(0, 0, -cm(1.7));
  C.rb(BW*0.72, BL*0.64, cm(7), cm(3.4), fab, p[0], p[1]-BL*0.32, p[2], 5).rotation.x = -th;
  const weltPts = padPts.map(q=>[q[0]*1.012, q[1]*1.012]);
  for(const lz of [cm(0.2), BT-2*bev-cm(0.4)]){
    p = bxf(0, 0, lz);
    C.ext(weltPts, cm(1.4), fabD, p[0],p[1],p[2], 'xy', cm(0.6)).rotation.x = -th;
  }
  for(const sx of [-1,0,1]) for(const sy of [-1,0,1]){
    p = bxf(sx*cm(13), sy*cm(8.6), cm(12.25));
    C.rb(cm(19), cm(12.5), cm(7.5), cm(3.4), fab, p[0], p[1]-cm(6.25), p[2], 4).rotation.x = -th;
  }
  for(const sx of [-1,1]) for(const sy of [-1,1]){
    p = bxf(sx*cm(6.5), sy*cm(4.3), cm(13.9));
    const b = C.sph(cm(1.9), fabD, p[0],p[1],p[2], 14);
    b.rotation.x = -th; b.scale.z = 0.62;
  }

  /* ========== 坐垫：厚实方圆软垫，前高后低 3.4°，3×3 绗缝 + 4 颗包扣 + 一圈包边缝，前沿留厚圆卷边 ========== */
  const st = 0.06, cS = Math.cos(st), sS = Math.sin(st);
  const ST = cm(17), SD = cm(60), SW = C.w;
  const scz = halfD - (SD/2)*cS;
  const scy = C.seatH - (ST/2)*cS - cm(4.2);
  const sxf = (lx,ly,lz) => [lx, scy + ly*cS + lz*sS, scz - ly*sS + lz*cS];
  const sRb = (w,h,d,r,mat,lx,ly,lz,seg) => {
    const q = sxf(lx,ly,lz);
    C.rb(w,h,d,r,mat,q[0],q[1]-h/2,q[2],seg).rotation.x = -st;
  };
  sRb(SW-cm(0.9), ST, SD-cm(0.9), cm(5.6), fab, 0, 0, 0, 4);
  sRb(SW, cm(1.9), SD, cm(0.95), fabD, 0, cm(2.2), 0, 3);
  for(const sx of [-1,0,1]) for(const sz of [-1,0,1])
    sRb(cm(23), cm(9.5), cm(18), cm(4.6), fab, sx*cm(18), cm(7.95), sz*cm(13.5), 4);
  for(const sx of [-1,1]) for(const sz of [-1,1]){
    p = sxf(sx*cm(9), cm(10.6), sz*cm(6.75));
    const b = C.sph(cm(1.9), fabD, p[0],p[1],p[2], 14);
    b.rotation.x = -st; b.scale.y = 0.62;
  }

  /* ========== 坐垫下方向内急收的软包喇叭座：它与地面之间真的镂空，只剩镀铬轴与星脚 ========== */
  C.lathe([[cm(3.9),cm(15.6)],[cm(4.8),cm(16.6)],[cm(7.5),cm(18.4)],[cm(11.5),cm(20.4)],
           [cm(15.5),cm(22.2)],[cm(18.5),cm(24.0)],[cm(20.0),cm(26.0)],[cm(20.4),cm(28.0)]],
          fab, 0, 0, 0, 30);

  /* ========== 旋转五金：黑色塑料轴套 + 车削感镀铬轴座（360° 旋转） ========== */
  C.cyl(cm(4.3), cm(4.8), cm(4.2), blk, 0, cm(12.6), 0, 22);
  C.lathe([[cm(0.1),cm(6.2)],[cm(4.9),cm(6.2)],[cm(6.4),cm(7.6)],[cm(6.5),cm(10.4)],
           [cm(5.6),cm(12.2)],[cm(5.0),cm(13.4)],[cm(0.1),cm(13.4)]], chrome, 0, 0, 0, 28);

  /* ========== 镀铬五星脚：扁刀状辐条自轴座外张下斜、末端压平落地并带黑色脚垫（无滚轮），一条正对后方防倾 ========== */
  const R0 = cm(4.2), R1 = C.w*0.46, RL = R1-R0;
  const legPts = [
    [R0, cm(13.4)], [R0+RL*0.22, cm(9.6)], [R0+RL*0.52, cm(6.0)], [R0+RL*0.80, cm(3.6)],
    [R1-cm(1.2), cm(3.0)], [R1, cm(2.7)], [R1, cm(0.7)], [R1-cm(2.0), cm(0.65)],
    [R0+RL*0.72, cm(1.9)], [R0+RL*0.40, cm(4.0)], [R0+RL*0.14, cm(6.6)], [R0, cm(8.0)]
  ];
  const legD = cm(3.9), legB = cm(0.7), zc = legD/2 - legB, rGl = R1 - cm(1.7);
  C.rep(5, (i) => {
    const a = Math.PI*2*i/5;
    C.ext(legPts, legD, chrome, -zc*Math.cos(a), 0, zc*Math.sin(a), 'zy', legB).rotation.y = Math.PI/2 + a;
    C.rb(cm(3.2), cm(0.95), cm(4.2), cm(0.4), blk, -rGl*Math.sin(a), 0, -rGl*Math.cos(a)).rotation.y = a;
  });
};

orfjall:
MODELS['orfjall'] = (C) => {
  const cm=C.cm, T=C.THREE, D=Math.PI/180;
  const FC = C.col2 ? C.col2.clone() : new T.Color(0xf2f0ea);
  const mSteel = C.M(FC, {rough:.34, metal:.10, clear:.40, clearRough:.26});
  const mPla   = C.M(FC, {rough:.52, metal:.02, clear:.18, clearRough:.40});
  const mPlaD  = C.M(FC.clone().multiplyScalar(.80), {rough:.58, metal:.02});
  const mDark  = C.M(FC.clone().multiplyScalar(.20), {rough:.40, metal:.25});
  const mMech  = C.M(0x44484e, {rough:.52, metal:.30});
  const mFab   = C.m.fab;

  const dY = (C.seatH || cm(47)) - cm(47);
  const Y  = (v)=> cm(v) + dY;
  const TH=13*D, cT=Math.cos(TH), sT=Math.sin(TH);
  const A=23.5, B=20.8, E=.72, TAP=.13, RIMY=43.0;
  const BY=52.0, BZ=-18.5, BU=18.0, VTOP=29.7, CR=8.5, VC=VTOP-CR;
  const R=cm(1.1);

  const link=(a,b,mat)=>{
    const dx=b[0]-a[0], dy=b[1]-a[1], dz=b[2]-a[2];
    const L=Math.sqrt(dx*dx+dy*dy+dz*dz);
    if(L<1e-5) return null;
    const m=C.tube(L+2*R, R, mat, (a[0]+b[0])/2, (a[1]+b[1])/2, (a[2]+b[2])/2, 'y');
    m.quaternion.setFromUnitVectors(new T.Vector3(0,1,0), new T.Vector3(dx/L,dy/L,dz/L));
    return m;
  };
  const oval=(aa,bb,ee,tp,n)=>{
    const o=[];
    for(let i=0;i<n;i++){
      const t=i/n*Math.PI*2, s=Math.sin(t), c=Math.cos(t);
      const sx=(s<0?-1:1)*Math.pow(Math.abs(s),ee), cz=(c<0?-1:1)*Math.pow(Math.abs(c),ee);
      o.push([cm(aa*sx*(1-tp*Math.max(0,-c))), cm(bb*cz)]);
    }
    return o;
  };
  const rimPt=(ph)=>{
    const s=Math.sin(ph*D), c=Math.cos(ph*D);
    const sx=(s<0?-1:1)*Math.pow(Math.abs(s),E), cz=(c<0?-1:1)*Math.pow(Math.abs(c),E);
    return [cm(A*sx*(1-TAP*Math.max(0,-c))), Y(RIMY), cm(B*cz)];
  };
  const bp=(u,v)=>[cm(u), Y(BY+v*cT), cm(BZ-v*sT)];
  const riser=(sg)=>{
    const P0=rimPt(sg*125), P3=bp(sg*BU,0);
    const P1=[cm(sg*19.5), Y(44.4), cm(-18.6)];
    const P2=[cm(sg*BU),   Y(BY-5*cT), cm(BZ+5*sT)];
    const o=[];
    for(let i=1;i<=5;i++){
      const t=i/5, k=1-t, q=[];
      for(let j=0;j<3;j++) q.push(k*k*k*P0[j]+3*k*k*t*P1[j]+3*k*t*t*P2[j]+t*t*t*P3[j]);
      o.push(q);
    }
    return o;
  };

  const P=[], NR=25;
  for(let i=0;i<NR;i++) P.push(rimPt(-125+250*i/(NR-1)));
  riser(1).forEach(q=>P.push(q));
  [6,12,18].forEach(v=>P.push(bp(BU,v)));
  for(let i=1;i<=5;i++){ const a=90*i/5*D; P.push(bp(BU-CR+CR*Math.cos(a), VC+CR*Math.sin(a))); }
  [4.75,0,-4.75].forEach(u=>P.push(bp(u,VTOP)));
  for(let i=5;i>=0;i--){ const a=90*i/5*D; P.push(bp(-(BU-CR)-CR*Math.cos(a), VC+CR*Math.sin(a))); }
  [18,12,6].forEach(v=>P.push(bp(-BU,v)));
  const lr=riser(-1);
  for(let i=lr.length-1;i>=0;i--) P.push(lr[i]);
  for(let i=0;i<P.length;i++) link(P[i], P[(i+1)%P.length], mSteel);

  C.ext(oval(23.6,20.9,E,TAP,30), cm(1.4), mPla, 0, Y(42.15), 0, 'xz', cm(.45));
  C.ext(oval(22.3,19.6,E,TAP,30), cm(4.4), mFab,  0, Y(44.8), 0, 'xz', cm(1.5));
  C.ext(oval(21.3,18.7,E,TAP,26), cm(1.7), mFab,  0, Y(45.8), 0, 'xz', cm(1.2));

  const put=(m,q)=>{ m.position.set(q[0],q[1],q[2]); m.rotation.x=-TH; return m; };
  const bq=(u,v,off)=>[cm(u), Y(BY+v*cT)+cm(off)*sT, cm(BZ-v*sT)+cm(off)*cT];
  put(C.ext(oval(16.5,12.75,.68,.10,26), cm(4.4), mFab,  0,0,0,'xy', cm(1.4)), bq(0,14.6,1.1));
  put(C.ext(oval(15.4,11.8,.68,.10,22), cm(1.7), mFab,  0,0,0,'xy', cm(1.1)), bq(0,14.8,3.5));
  for(const sg of [-1,1]) for(const v of [10,20]){
    const q=bq(sg*17.1, v, 0.9);
    const cl=C.rb(cm(3.2), cm(1.9), cm(1.2), cm(.3), mPla, q[0], q[1]-cm(.95), q[2]);
    cl.rotation.x=-TH;
  }

  C.rb(cm(15), cm(1.1), cm(12.5), cm(.4), mMech, 0, Y(40.2), cm(-0.5));
  C.lathe([[cm(2.3),Y(37.2)],[cm(3.6),Y(37.9)],[cm(5.6),Y(39.1)],[cm(8.2),Y(40.6)],[cm(9.8),Y(41.6)],[cm(9.9),Y(42.1)]], mPla, 0,0,0, 26);
  C.tube(cm(13.5), cm(.5), mPla, cm(-15.5), Y(39.4), cm(4.0), 'x');
  C.rb(cm(6.0), cm(.8), cm(2.2), cm(.3), mPla, cm(-20.0), Y(39.0), cm(4.6));

  C.cyl(cm(1.95), cm(1.95), cm(2.2), mPla,  0, Y(35.9), 0, 20);
  C.cyl(cm(1.72), cm(1.72), cm(2.4), mDark, 0, Y(33.7), 0, 20);
  const colB=cm(9.6), colT=Y(34.0);
  C.cyl(cm(2.45), cm(2.62), colT-colB, mPla, 0, colB, 0, 22);
  C.lathe([[cm(3.4),cm(3.4)],[cm(5.3),cm(4.4)],[cm(5.5),cm(7.4)],[cm(4.3),cm(9.4)],[cm(3.0),cm(10.0)]], mPla, 0,0,0, 26);

  const prof=[[0,4.4],[27.2,4.25],[29.8,5.0],[29.8,6.6],[27.2,7.7],[0,9.9]].map(p=>[cm(p[0]),cm(p[1])]);
  const AW=cm(4.7), AB=cm(.7);
  C.rep(5,(i)=>{
    const psi=i*72*D, sp=Math.sin(psi), cp=Math.cos(psi);
    const arm=C.ext(prof, AW, mPla, 0, 0, 0, 'xy', AB);
    arm.geometry.translate(0,0,-(AW-2*AB)/2);
    arm.rotation.y = psi - Math.PI/2;
    const hx=cm(29.3)*sp, hz=cm(29.3)*cp;
    const hs=C.rb(cm(5.6), cm(2.9), cm(4.6), cm(.9), mPlaD, hx, cm(3.2), hz);
    hs.rotation.y=psi;
    for(const s of [-1,1]){
      const wx=cm(30.5)*sp + s*cm(2.05)*cp, wz=cm(30.5)*cp - s*cm(2.05)*sp;
      const w=C.cyl(cm(2.75), cm(2.75), cm(1.5), mPlaD, wx, cm(2.75)-cm(.75), wz, 20);
      w.rotation.z=Math.PI/2; w.rotation.y=psi;
    }
  });
};

idasen-desk:
MODELS['idasen-desk'] = (C) => {
  const T3 = C.THREE, cm = C.cm, PI = Math.PI;
  const hw = C.w / 2, hd = C.d / 2;
  /* 官方 h=127 是电动升降的最高位；室内摆放按坐姿 73cm 呈现（可用区间 63–127） */
  const H = C.h > cm(95) ? cm(73) : C.h;
  const TT = cm(3.0), bev = cm(0.30), yU = H - TT;
  /* C.rb 的圆角半径会向外扩张，包一层保证实际外形正好是 w×h×d、底面落在 y */
  const rbox = (w, h, d, r, mat, x, y, z) => C.rb(w - 2 * r, h - 2 * r, d, r, mat, x, y + r, z, 3);

  const frameC = C.col2 || new T3.Color(0x4c4f52);
  const steelM = C.M(frameC, {rough:.52, metal:.26, clear:.08, clearRough:.55});
  const darkM  = C.M(new T3.Color(frameC).multiplyScalar(.50), {rough:.62, metal:.10});
  const netM   = C.M(new T3.Color(frameC).multiplyScalar(.42), {rough:.68, metal:.30});
  const gripM  = C.M(new T3.Color(frameC).multiplyScalar(1.20), {rough:.46, metal:.14});
  const topM   = C.M(C.col, {wood:'ash', rough:.50, clear:.34, clearRough:.28});
  if (topM.map) { topM.map = topM.map.clone(); topM.map.needsUpdate = true; topM.map.repeat.set(.55, .55); }
  if (topM.normalMap) { topM.normalMap = topM.normalMap.clone();
    topM.normalMap.needsUpdate = true; topM.normalMap.repeat.set(.55, .55); }

  /* 桌面：160×80×3 梣木贴皮板，四角小圆角，四边塑料封边微倒角 */
  const cr = cm(1.4) - bev, ow = hw - bev, od = hd - bev, tp = [];
  const arc = (cx, cz, r, a0, a1, n) => { for (let i = 0; i <= n; i++) {
    const a = a0 + (a1 - a0) * i / n; tp.push([cx + Math.cos(a) * r, cz + Math.sin(a) * r]); } };
  arc(-ow + cr, -od + cr, cr, PI, PI * 1.5, 4);
  arc( ow - cr, -od + cr, cr, PI * 1.5, PI * 2, 4);
  arc( ow - cr,  od - cr, cr, 0, PI * 0.5, 4);
  arc(-ow + cr,  od - cr, cr, PI * 0.5, PI, 4);
  C.ext(tp, TT, topM, 0, H - bev, 0, 'xz', bev);

  /* 双柱电动升降架：立柱内缩约 19cm，底架前后跨 70cm */
  const legX = Math.max(hw * 0.55, hw - cm(19));
  const footZ = Math.min(hd - cm(5), cm(35));
  const brH = cm(3.4), brZ = footZ - cm(5), brW = cm(9), bb = cm(0.5);
  const railY = cm(2.4), colTop = yU - brH;
  const yB = Math.min(cm(56), colTop * 0.84);
  const e = Math.max(cm(0.6), (colTop - yB) / 2);
  const rB = cm(3.60), rM = cm(3.05), rT = cm(2.60);
  const yBr = Math.min(cm(40), yB * 0.72);
  const dz0 = cm(3.2), dz1 = footZ - cm(3.0), y0 = yBr, y1 = cm(1.6);
  const dL = Math.hypot(dz1 - dz0, y0 - y1), dA = Math.atan2(dz1 - dz0, y0 - y1);

  for (const s of [-1, 1]) {
    const X = s * legX;
    /* 顶部安装钢板：前后细长、两端收窄，紧贴桌面底面 */
    const bp = [[-brW + bb, -brZ + cm(8)], [-brW + cm(3.6), -brZ + bb], [brW - cm(3.6), -brZ + bb],
                [brW - bb, -brZ + cm(8)], [brW - bb, brZ - cm(9)], [brW - cm(4.2), brZ - bb],
                [-brW + cm(4.2), brZ - bb], [-brW + bb, brZ - cm(9)]];
    C.ext(bp, brH, steelM, X, yU - cm(0.55), 0, 'xz', bb);
    for (const t of [-1, 1])
      C.cyl(cm(0.55), cm(0.55), cm(0.4), darkM, X + t * cm(4.4), yU - brH - cm(0.4), cm(4), 10);
    /* 三级伸缩圆管：上细下粗，每级接缝处一圈稍粗的箍 */
    C.cyl(rB, rB, yB - railY, steelM, X, railY, 0, 24);
    C.cyl(rB * 1.04, rB * 1.04, cm(1.3), steelM, X, yB - cm(1.3), 0, 24);
    C.cyl(rM, rM, e + cm(1.4), steelM, X, yB - cm(1.4), 0, 24);
    C.cyl(rM * 1.05, rM * 1.05, cm(1.1), steelM, X, yB + e - cm(1.1), 0, 24);
    C.cyl(rT, rT, colTop - yB - e + cm(1.2), steelM, X, yB + e - cm(1.2), 0, 24);
    C.cyl(rT * 1.38, rT * 1.38, cm(1.6), steelM, X, colTop - cm(1.6), 0, 20);
    /* Y 形底架：两根扁圆斜撑向前后撇开 + 落地扁脚条 + 椭圆脚垫 */
    for (const t of [-1, 1]) {
      const m = C.tube(dL, cm(2.5), steelM, X + t * cm(1.2), (y0 + y1) / 2, t * (dz0 + dz1) / 2, 'y');
      m.scale.x = 0.62; m.rotation.x = -t * dA;
      const L2 = footZ - cm(1.2);
      rbox(cm(3.6), railY, L2, cm(0.5), steelM, X + t * cm(1.5), 0, t * L2 / 2);
      const gl = C.cyl(cm(3.2), cm(3.0), cm(1.6), darkM, X + t * cm(1.5), 0, t * dz1, 18);
      gl.scale.x = 0.68;
    }
  }

  /* 贯通横梁（可伸缩，配 160×80 桌面时约 146cm），紧贴桌面底、靠后侧 */
  const railHW = Math.min(hw - cm(7), legX + cm(12));
  rbox(railHW * 2, cm(4.6), cm(6.4), cm(0.6), steelM, 0, yU - cm(5.0), -cm(15));

  /* 理线网：桌面下方一片浅浅的钢丝网兜（纵丝 + U 形横肋，真镂空） */
  const nX = legX - cm(7), nZ = cm(9.5), nDrop = cm(5.5), nY = yU - cm(0.4), nZc = cm(1.5);
  const prof = a => -nDrop * (1 - (a / nZ) * (a / nZ));
  for (let i = 0; i < 5; i++) { const a = -nZ + 2 * nZ * i / 4;
    C.tube(nX * 2, cm(0.30), netM, 0, nY + prof(a) - cm(0.30), nZc + a, 'x'); }
  const rib = [], NR = 8;
  for (let i = 0; i <= NR; i++) { const a = -nZ + 2 * nZ * i / NR; rib.push([a, prof(a)]); }
  for (let i = NR; i >= 0; i--) { const a = -nZ + 2 * nZ * i / NR; rib.push([a, prof(a) - cm(0.45)]); }
  C.rep(12, (i, t) => C.ext(rib, cm(0.45), netM, -nX + 2 * nX * t - cm(0.22), nY, nZc, 'zy'));

  /* 升降控制手柄：桌面右前方下沿的一小块深灰塑料手柄 */
  const hX = C.w * 0.16, zF = hd - cm(0.8);
  rbox(cm(13), cm(1.8), cm(9), cm(0.5), gripM, hX, yU - cm(1.8), zF - cm(4.6));
  rbox(cm(7.2), cm(2.6), cm(1.9), cm(0.45), gripM, hX, yU - cm(4.0), zF - cm(0.95));
};

sniglar-crib:
MODELS['sniglar-crib'] = (C) => {
  const cm = C.cm;
  const beech  = C.M(C.col, {wood:'beech', rough:.66, clear:.05, clearRough:.55});
  const beech2 = C.M(C.col2 || C.col.clone().multiplyScalar(.93), {wood:'beech', rough:.74, clear:.02, clearRough:.65});
  const bolt   = C.M(C.col.clone().lerp(new C.THREE.Color(0xb9bec4), .8), {rough:.3, metal:.7});

  const hw = C.w/2, hd = C.d/2;
  const P  = cm(3.2);
  const T  = cm(2.2);
  const TRh = cm(3.2);
  const BRy = cm(17.0), BRh = cm(4.8);
  const SW = cm(2.0), SD = cm(1.9), SR = cm(0.55);
  const ER = cm(0.3);
  const sy = BRy + BRh - cm(0.7);
  const sH = (C.h - TRh + cm(0.6)) - sy;
  const inX = C.w - 2*P, inZ = C.d - 2*P;

  for (const sx of [-1, 1]) for (const sz of [-1, 1])
    C.rb(P, C.h, P, ER, beech, sx*(hw - P/2), 0, sz*(hd - P/2 - cm(0.05)), 2);

  for (const sx of [-1, 1]) {
    const x = sx*(hw - T/2);
    C.rb(T, TRh, C.d, ER, beech, x, C.h - TRh, 0, 2);
    C.rb(T, BRh, C.d, ER, beech, x, BRy, 0, 2);
  }
  for (const sz of [-1, 1]) {
    const z = sz*(hd - T/2);
    C.rb(inX, TRh, T, ER, beech, 0, C.h - TRh, z, 2);
    C.rb(inX, BRh, T, ER, beech, 0, BRy, z, 2);
  }

  const stepX = inX/19;
  for (const sz of [-1, 1]) {
    const z = sz*(hd - cm(0.15) - SD/2);
    C.rep(18, (i) => C.rb(SW, sH, SD, SR, beech, -inX/2 + stepX*(i + 1), sy, z, 2));
  }
  const stepZ = inZ/10;
  for (const sx of [-1, 1]) {
    const x = sx*(hw - cm(0.15) - SD/2);
    C.rep(9, (i) => C.rb(SD, sH, SW, SR, beech, x, sy, -inZ/2 + stepZ*(i + 1), 2));
  }

  const bTop = cm(20.6), fT = cm(2.0), fH = cm(3.6);
  const bw = C.w - 2*T - cm(0.4), bd = C.d - 2*T - cm(0.4);
  for (const sz of [-1, 1])
    C.rb(bw, fH, fT, cm(0.25), beech2, 0, bTop - fH, sz*(bd/2 - fT/2), 2);
  for (const sx of [-1, 1])
    C.rb(fT, fH, bd - 2*fT, cm(0.25), beech2, sx*(bw/2 - fT/2), bTop - fH, 0, 2);
  const bsW = cm(5.0), bsT = cm(1.3), bsSpan = bw - 2*fT - bsW;
  C.rep(11, (i, t) => C.rb(bsW, bsT, bd - 2*fT, cm(0.2), beech2,
    (t - 0.5)*bsSpan, bTop - bsT, 0, 2));

  for (const sx of [-1, 1]) for (const sz of [-1, 1])
    for (const by of [C.h - TRh/2, BRy + BRh/2]) {
      const b = C.cyl(cm(0.55), cm(0.55), cm(0.3), bolt,
        sx*(hw - P/2), by - cm(0.15), sz*(hd - cm(0.15)), 14);
      b.rotation.x = Math.PI/2;
    }
};

raskog:
MODELS['raskog'] = (C) => {
  const T = C.THREE, cm = C.cm, hw = C.w / 2, hd = C.d / 2, H = C.h;
  const paint = C.M(C.col, {rough:.36, metal:.22, clear:.30, clearRough:.28});
  const dark  = C.M(C.col2 || 0x2f3236, {rough:.46, metal:.08});
  const grey  = C.m.steel, chrome = C.m.chrome;

  const tr = cm(0.85);
  const postX = cm(6.6), postZ = hd - cm(1.45);
  const railX = hw - tr - cm(0.35);
  const yRail = H * 0.1450, yPostBot = H * 0.2715, yPostTop = H - cm(0.45);
  const railEnd = cm(15.0), castZ = cm(18.3);
  const tHW = hw - cm(1.0), tHD = postZ - tr;

  const rrPath = (p, a, b, r) => {
    p.moveTo(a, b - r);
    p.absarc(a - r, b - r, r, 0, Math.PI / 2, false);
    p.lineTo(-(a - r), b);
    p.absarc(-(a - r), b - r, r, Math.PI / 2, Math.PI, false);
    p.lineTo(-a, -(b - r));
    p.absarc(-(a - r), -(b - r), r, Math.PI, Math.PI * 1.5, false);
    p.lineTo(a - r, -b);
    p.absarc(a - r, -(b - r), r, Math.PI * 1.5, Math.PI * 2, false);
    p.lineTo(a, b - r);
  };
  const emit = (shape, depth, bev, mat, y0) => {
    const geo = new T.ExtrudeGeometry(shape, {depth: Math.max(0.004, depth - 2 * bev),
      bevelEnabled: bev > 0, bevelSize: bev, bevelThickness: bev, bevelSegments: 2,
      curveSegments: 7, steps: 1});
    geo.rotateX(-Math.PI / 2); geo.computeVertexNormals();
    const mm = new T.Mesh(geo, mat);
    mm.position.set(0, y0 + bev, 0);
    mm.castShadow = mm.receiveShadow = true; C.g.add(mm); return mm;
  };
  const ring = (a, b, r, t, h, bev, mat, y0) => {
    const sh = new T.Shape(); rrPath(sh, a, b, r);
    const ho = new T.Path(); rrPath(ho, a - t, b - t, Math.max(cm(0.2), r - t));
    sh.holes.push(ho);
    return emit(sh, h, bev, mat, y0);
  };
  const meshFloor = (a, b, t, mat, y0) => {
    const sh = new T.Shape(); rrPath(sh, a, b, cm(1.4));
    const mx = a * 2 - cm(4.6), mz = b * 2 - cm(4.6);
    const nx = Math.max(3, Math.round(mx / cm(3.3))), nz = Math.max(3, Math.round(mz / cm(3.3)));
    const px = mx / nx, pz = mz / nz, rx = px * 0.43, rz = pz * 0.43;
    for (let i = 0; i < nx; i++) for (let j = 0; j < nz; j++) {
      const cx = -mx / 2 + (i + 0.5) * px, cz = -mz / 2 + (j + 0.5) * pz;
      const ph = new T.Path();
      ph.moveTo(cx, cz - rz); ph.lineTo(cx + rx, cz); ph.lineTo(cx, cz + rz);
      ph.lineTo(cx - rx, cz); ph.lineTo(cx, cz - rz);
      sh.holes.push(ph);
    }
    return emit(sh, t, 0, mat, y0);
  };
  const seg = (p, q, r, mat) => {
    const d = new T.Vector3(q[0] - p[0], q[1] - p[1], q[2] - p[2]);
    const L = d.length();
    const mm = C.tube(L, r, mat, (p[0] + q[0]) / 2, (p[1] + q[1]) / 2, (p[2] + q[2]) / 2, 'y');
    mm.quaternion.setFromUnitVectors(new T.Vector3(0, 1, 0), d.normalize());
    return mm;
  };
  const bend = (pts, n, r, mat) => {
    const cv = new T.CatmullRomCurve3(pts.map(p => new T.Vector3(p[0], p[1], p[2])), false, 'centripetal');
    const ps = cv.getPoints(n);
    for (let i = 0; i < n; i++) seg([ps[i].x, ps[i].y, ps[i].z], [ps[i + 1].x, ps[i + 1].y, ps[i + 1].z], r, mat);
  };

  for (const sx of [-1, 1]) {
    seg([sx * railX, yRail, -railEnd], [sx * railX, yRail, railEnd], tr, paint);
    for (const sz of [-1, 1]) {
      seg([sx * postX, yPostBot, sz * postZ], [sx * postX, yPostTop, sz * postZ], tr, paint);
      bend([
        [sx * postX, yPostBot + cm(5.0), sz * postZ],
        [sx * postX, yPostBot, sz * postZ],
        [sx * postX, yRail + cm(4.2), sz * postZ],
        [sx * (postX + cm(4.6)), yRail + cm(0.9), sz * (postZ - cm(0.2))],
        [sx * railX, yRail, sz * (postZ - cm(2.5))],
        [sx * railX, yRail, sz * railEnd],
        [sx * railX, yRail, sz * (railEnd - cm(4.0))]
      ], 7, tr, paint);
      C.cyl(cm(1.05), cm(1.0), cm(0.62), paint, sx * postX, yPostTop - cm(0.2), sz * postZ, 18);

      const sw = sx * (railX - cm(0.65)), wx = sx * (railX - cm(2.7)), cz = sz * castZ;
      C.lathe([[cm(0.05), 0], [cm(1.42), 0], [cm(1.52), cm(0.4)], [cm(1.52), cm(1.9)],
               [cm(1.05), cm(2.3)], [cm(0.95), cm(3.5)], [cm(0.58), cm(3.8)], [cm(0.58), cm(5.4)]],
              grey, sw, cm(5.3), cz, 18);
      for (const s2 of [-1, 1])
        C.rb(cm(4.3), cm(4.7), cm(0.66), cm(0.5), grey, sx * (railX - cm(1.7)), cm(1.4), cz + s2 * cm(1.25));
      C.cyl(cm(2.5), cm(2.5), cm(1.75), dark, wx, cm(2.5) - cm(0.875), cz, 24).rotation.x = Math.PI / 2;
      C.cyl(cm(0.8), cm(0.8), cm(2.5), grey, wx, cm(2.5) - cm(1.25), cz, 14).rotation.x = Math.PI / 2;
    }
  }

  const trays = [[H * 0.1690, H * 0.1560], [H * 0.4870, H * 0.1560], [H * 0.8830, H - H * 0.8830]];
  for (const t of trays) {
    const y0 = t[0], th = t[1], top = y0 + th;
    ring(tHW, tHD, cm(2.8), cm(0.45), th, cm(0.16), paint, y0);
    ring(tHW - cm(0.05), tHD - cm(0.05), cm(2.75), cm(1.5), cm(2.0), cm(0.68), paint, y0);
    ring(tHW + cm(0.22), tHD + cm(0.22), cm(3.0), cm(0.95), cm(1.15), cm(0.42), paint, top - cm(1.15));
    meshFloor(tHW - cm(0.55), tHD - cm(0.55), cm(0.28), paint, y0 + cm(1.75));
    for (const sz of [-1, 1]) {
      C.rb(cm(15.6), cm(7.4), cm(0.75), cm(0.9), paint, 0, top - cm(7.4), sz * (postZ + cm(1.05)));
      C.cyl(cm(0.62), cm(0.62), cm(0.34), chrome, 0, top - cm(3.9), sz * (postZ + cm(1.12)), 14).rotation.x = Math.PI / 2;
    }
  }
};

kallax-a:
MODELS['kallax-a'] = (C) => {
  const W = C.w, D = C.d, H = C.h;
  const F  = C.cm(3.9);
  const T  = C.cm(1.6);
  const EB = C.cm(0.16);
  const CELL = C.cm(33.5);
  const cols = Math.max(1, Math.round((W - 2*F + T) / (CELL + T)));
  const rows = Math.max(1, Math.round((H - 2*F + T) / (CELL + T)));
  const innerW = W - 2*F, innerH = H - 2*F;
  const cw = (innerW - (cols - 1) * T) / cols;
  const ch = (innerH - (rows - 1) * T) / rows;
  const body = C.M(C.col, {rough:.80});
  const edge = C.M(C.col2 ? C.col.clone().lerp(C.col2, .55) : C.col, {rough:.50});
  const fitM = C.M(C.col.clone().lerp(new C.THREE.Color(0xdadad6), .55), {rough:.45});
  const core = D - 2*EB, zb = (D - EB) / 2;
  const plate = (w, h, x, y, ends) => {
    const wc = ends ? w - 2*EB : w;
    C.box(wc, h, core, body, x, y, 0);
    C.box(wc, h, EB, edge, x, y,  zb);
    C.box(wc, h, EB, edge, x, y, -zb);
    if (ends) for (const s of [-1, 1]) C.box(EB, h, D, edge, x + s * (w - EB) / 2, y, 0);
  };
  plate(W, F, 0, 0, 1);
  plate(W, F, 0, H - F, 1);
  for (const s of [-1, 1]) plate(F, innerH, s * (W - F) / 2, F, 0);
  C.rep(rows - 1, (j) => plate(innerW, T, 0, F + (j + 1) * ch + j * T, 0));
  for (let i = 1; i < cols; i++) {
    const x = -W/2 + F + i * cw + (i - 0.5) * T;
    C.rep(rows, (r) => plate(T, ch, x, F + r * (ch + T), 0));
  }
  const fx = -W/2 + F + cw * 0.72, fz = -D/2 + C.cm(6);
  C.box(C.cm(3.8), C.cm(5.0), C.cm(1.1), fitM, fx, H - F - C.cm(5.0), fz);
  C.box(C.cm(2.2), C.cm(1.0), C.cm(4.0), fitM, fx, H - F - C.cm(1.0), fz - C.cm(1.5));
};

figgy:
MODELS['figgy'] = (C) => {
  const acc  = C.col2 ? C.col.clone().lerp(C.col2, 0.5) : C.col.clone();
  const fab  = C.M(C.col, {fabric:true, rough:.93, sheen:.30});
  const web  = C.M(acc.clone().multiplyScalar(.84), {fabric:true, rough:.99});
  const zip  = C.M(acc.clone().multiplyScalar(.62), {rough:.45, metal:.20});
  const tagW = C.M(0xf2f0e8, {rough:.85});
  const tagG = C.M(0x3d7a4b, {rough:.85});
  const S = (w, h, d, r, mat, x, y, z, seg) => {
    const rr = Math.max(0.006, Math.min(r, w/4 - 0.002, h/4 - 0.002, d/2 - 0.004));
    return C.rb(Math.max(w - 2*rr, 0.01), Math.max(h - 2*rr, 0.01), d, rr, mat, x, y + rr, z, seg);
  };
  const pad = C.cm(0.6);
  const grip = (fx, fy, fz, dir) => {
    const L = C.cm(20), th = C.cm(3.2), t = C.cm(1.2);
    const eh = th + C.cm(1.6), ew = C.cm(3.4);
    if (dir === 0) {
      S(L, th, t, C.cm(0.35), web, fx, fy - th/2, fz + pad - t/2, 2);
      for (const s of [-1,1])
        S(ew, eh, t*0.86, C.cm(0.3), web, fx + s*(L/2 - ew/2), fy - eh/2, fz + pad - t*0.63, 2);
    } else {
      S(t, th, L, C.cm(0.35), web, fx + dir*(pad - t/2), fy - th/2, fz, 2);
      for (const s of [-1,1])
        S(t*0.86, eh, ew, C.cm(0.3), web, fx + dir*(pad - t*0.63), fy - eh/2, fz + s*(L/2 - ew/2), 2);
    }
  };
  const tag = (x, y, z, dir) => {
    if (dir === 0) {
      S(C.cm(4.2), C.cm(2.6), C.cm(0.7), C.cm(0.12), tagW, x, y, z, 2);
      S(C.cm(2.6), C.cm(0.7), C.cm(0.8), C.cm(0.1), tagG, x, y + C.cm(0.95), z, 2);
    } else {
      S(C.cm(0.7), C.cm(2.6), C.cm(4.2), C.cm(0.12), tagW, x, y, z, 2);
      S(C.cm(0.8), C.cm(0.7), C.cm(2.6), C.cm(0.1), tagG, x, y + C.cm(0.95), z, 2);
    }
  };
  const gap = C.cm(1.2);
  const bw = (C.w - gap)/2 - pad, bd = C.d - pad, bt = C.seatH/2, zc = -pad/2;
  const deckR = C.w/2 - pad, deckF = C.d/2 - pad, deckB = -C.d/2;
  for (const sx of [-1,1]) {
    const cx = sx*(bw + gap)/2;
    for (let lv = 0; lv < 2; lv++) {
      const y = lv*bt;
      S(bw, bt, bd, C.cm(3.2), fab, cx, y, zc, 4);
      S(bw - C.cm(13), C.cm(0.7), C.cm(0.5), C.cm(0.2), zip, cx, y + C.cm(1.5), deckF - C.cm(0.16), 2);
      grip(cx, y + bt/2, deckF, 0);
      grip(sx*deckR, y + bt/2, zc + C.cm(3), sx);
    }
    S(bw - C.cm(11), C.cm(1.6), bd - C.cm(11), C.cm(0.8), fab, cx, C.seatH - C.cm(1.1), zc, 3);
  }
  tag(deckR - C.cm(16), C.seatH - C.cm(4.4), deckF - C.cm(0.1), 0);
  const bolW = C.cm(55.9), bolD = C.cm(27.9), bolH = C.h - C.seatH - C.cm(0.4), g2 = C.cm(0.9);
  const bz = deckB + bolD/2;
  for (const sx of [-1,1]) {
    const bx = sx*(bolW + g2)/2;
    S(bolW, bolH, bolD, C.cm(4.2), fab, bx, C.seatH, bz, 4);
    S(bolW - C.cm(10), C.cm(1.4), bolD - C.cm(8), C.cm(0.7), fab, bx, C.seatH + bolH - C.cm(1.0), bz, 3);
    S(bolW - C.cm(14), C.cm(0.7), C.cm(0.5), C.cm(0.2), zip, bx, C.seatH + C.cm(2.4), bz + bolD/2 - C.cm(0.16), 2);
    grip(bx, C.seatH + bolH*0.48, bz + bolD/2, 0);
  }
  const wW = C.cm(55.9), wL = C.cm(38.1), wH = C.cm(27.9);
  const rin = (wL + wH - Math.hypot(wL, wH))/2, bev = Math.min(C.cm(1.7), rin*0.45);
  const k = (rin - bev)/rin, ix = wL - rin, iy = rin;
  const P = (px, py) => [ix + k*(px - ix), iy + k*(py - iy)];
  const wx = deckR - wL, wzF = deckF;
  C.ext([P(0,0), P(wL,0), P(wL,wH)], wW, fab, wx, C.seatH, wzF - wW + bev, 'xy', bev);
  S(C.cm(0.5), C.cm(0.7), wW - C.cm(12), C.cm(0.2), zip, deckR - C.cm(0.16), C.seatH + C.cm(1.5), wzF - wW/2, 2);
  grip(deckR, C.seatH + wH*0.42, wzF - wW/2, 1);
  tag(deckR - C.cm(0.1), C.seatH + C.cm(4.6), wzF - C.cm(10), 1);
};

kallax-b:
MODELS['kallax-b'] = (C) => {
  const W = C.w, D = C.d, H = C.h;
  const NX = 4, NY = 4;
  const F = C.cm(3.9);
  const T = C.cm(1.6);
  const EB = C.cm(0.16);
  const CAP = C.cm(0.05);
  const innerW = W - 2 * F, innerH = H - 2 * F;
  const cw = (innerW - (NX - 1) * T) / NX;
  const ch = (innerH - (NY - 1) * T) / NY;
  const din = D - C.cm(0.8);
  const grain = !!C.col2;
  const bodyM = grain
    ? C.M(C.col, {wood: true, rough: .60, clear: .12, clearRough: .50})
    : C.M(C.col, {rough: .66, clear: .12, clearRough: .44});
  const edgeM = C.M(C.col2 ? C.col.clone().lerp(C.col2, .32) : C.col, {rough: .46, clear: .22, clearRough: .26});
  const brkM = C.M(C.col, {rough: .68});
  const capM = C.M(0xc6cad0, {rough: .40, metal: .42});
  const plate = (w, h, x, y, ends, dp) => {
    const dz = dp || D, zb = (dz - EB) / 2, wc = ends ? w - 2 * EB : w;
    C.box(wc, h, dz - 2 * EB, bodyM, x, y, 0);
    C.box(wc, h, EB, edgeM, x, y, zb);
    C.box(wc, h, EB, edgeM, x, y, -zb);
    if (ends) for (const s of [-1, 1]) C.box(EB, h, dz, edgeM, x + s * (w - EB) / 2, y, 0);
  };

  plate(W, F, 0, 0, 1);
  plate(W, F - CAP, 0, H - F, 1);
  for (const s of [-1, 1]) plate(F, innerH, s * (W - F) / 2, F, 0);

  C.rep(NY - 1, (j) => plate(innerW, T, 0, F + (j + 1) * ch + j * T, 0, din));

  const vx = [-(W - F) / 2, (W - F) / 2];
  for (let i = 1; i < NX; i++) {
    const x = -W / 2 + F + i * cw + (i - 0.5) * T;
    vx.push(x);
    C.rep(NY, (r) => plate(T, ch, x, F + r * (ch + T), 0, din));
  }

  for (const x of vx) for (const s of [-1, 1])
    C.cyl(C.cm(0.45), C.cm(0.45), C.cm(0.19), capM, x, H - C.cm(0.19), s * (D / 2 - C.cm(7)), 12);

  for (const s of [-1, 1]) {
    C.box(C.cm(4.4), C.cm(4.4), C.cm(2.4), brkM, s * (W / 2 - F - C.cm(2.2)), H - F - C.cm(5.6), -D / 2 + C.cm(9));
    C.box(C.cm(2.0), C.cm(1.2), C.cm(3.6), brkM, s * (W / 2 - F - C.cm(1.0)), H - F - C.cm(1.2), -D / 2 + C.cm(7.6));
  }
};

kallax-d:
MODELS['kallax-d'] = (C) => {
  const W = C.w, D = C.d, H = C.h;
  const F = C.cm(3.9), T = C.cm(1.6);
  const iw = W - 2 * F, ih = H - 2 * F;
  const cols = Math.max(1, Math.round((iw + T) / (C.cm(33.5) + T)));
  const rows = Math.max(1, Math.round((ih + T) / (C.cm(33.5) + T)));
  const cw = (iw - (cols - 1) * T) / cols;
  const ch = (ih - (rows - 1) * T) / rows;
  const eb = C.cm(0.55), er = C.cm(0.18), cd = D - C.cm(0.9);
  const zV = D / 2 - eb / 2, zH = zV - C.cm(0.07);
  const tint = (t) => C.col.clone().lerp(C.col2 || C.col, 0.4).multiplyScalar(t);
  const face = C.M(C.col, {rough: .80, clear: .06, clearRough: .55});
  const edge = C.M(C.col.clone().lerp(C.col2 || C.col, 0.15), {rough: .55, clear: .22, clearRough: .30});
  const dkS = C.M(tint(.92), {rough: .86});
  const dkU = C.M(tint(.97), {rough: .84});
  const dkD = C.M(tint(.84), {rough: .88});
  const mSideL = [dkS, face, face, dkS, edge, edge];
  const mSideR = [face, dkS, face, dkS, edge, edge];
  const mTop = [face, face, face, dkD, edge, edge];
  const mBot = [face, face, dkU, dkS, edge, edge];
  const mVert = [dkS, dkS, face, face, edge, edge];
  const mShelf = [face, face, dkU, dkD, edge, edge];
  const band = (w, h, x, y, z) => C.rb(w - 2 * er, h - 2 * er, eb, er, edge, x, y + er, z, 3);
  const vx = [], sy = [], cx = [];
  for (let i = 0; i < cols; i++) {
    cx.push(-W / 2 + F + i * (cw + T) + cw / 2);
    if (i < cols - 1) vx.push(-W / 2 + F + (i + 1) * cw + i * T + T / 2);
  }
  for (let r = 0; r < rows - 1; r++) sy.push(F + (r + 1) * ch + r * T);
  C.box(F, H, cd, mSideL, -W / 2 + F / 2, 0, 0);
  C.box(F, H, cd, mSideR, W / 2 - F / 2, 0, 0);
  C.box(iw, F, cd, mBot, 0, 0, 0);
  C.box(iw, F, cd, mTop, 0, H - F, 0);
  for (const x of vx) C.box(T, ih, cd, mVert, x, F, 0);
  for (const y of sy) for (const x of cx) C.box(cw, T, cd, mShelf, x, y, 0);
  for (const s of [1, -1]) {
    band(F, H, -W / 2 + F / 2, 0, s * zV);
    band(F, H, W / 2 - F / 2, 0, s * zV);
    band(iw, F, 0, 0, s * zH);
    band(iw, F, 0, H - F, s * zH);
    for (const x of vx) band(T, ih, x, F, s * zV);
    for (const y of sy) band(iw, T, 0, y, s * zH);
  }
  const fit = C.M(C.col.clone().lerp(new C.THREE.Color(0xf2efe8), .45), {rough: .5});
  const fz = -D / 2 + C.cm(4.2);
  for (const fx of (cols > 2 ? [cx[1], cx[cols - 2]] : [0])) {
    C.box(C.cm(3.6), C.cm(4.6), C.cm(1.0), fit, fx, H - F - C.cm(4.6), fz);
    C.box(C.cm(2.2), C.cm(0.9), C.cm(3.4), fit, fx, H - F - C.cm(0.9), fz - C.cm(1.2));
  }
};
